head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf96000";
scwin.div_return_n = null;
scwin.fee_procs_stat_cd_1 = null;
scwin.fee_procs_stat_cd_2 = null;
scwin.fee_procs_stat_cd_9 = null;
scwin.div_return_y = null;
scwin.fee_msg_1 = null;
scwin.fee_msg_2 = null;
scwin.fee_msg_elw = null;
scwin.tr_prepayBal = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — elwBatchYn, returnYn, feeProcsStatCd, message

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.div_return_n = $c.util.getComponent('div_return_n');
        scwin.fee_procs_stat_cd_1 = $c.util.getComponent('fee_procs_stat_cd_1');
        scwin.fee_procs_stat_cd_2 = $c.util.getComponent('fee_procs_stat_cd_2');
        scwin.fee_procs_stat_cd_9 = $c.util.getComponent('fee_procs_stat_cd_9');
        scwin.div_return_y = $c.util.getComponent('div_return_y');
        scwin.fee_msg_1 = $c.util.getComponent('fee_msg_1');
        scwin.fee_msg_2 = $c.util.getComponent('fee_msg_2');
        scwin.fee_msg_elw = $c.util.getComponent('fee_msg_elw');
        scwin.tr_prepayBal = $c.util.getComponent('tr_prepayBal');
        await scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf96000.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_listDutyRsn", fn: function(){ return (!(String(((dma_feeVO.get("listDutyRsn") ?? (() => { throw new Error("unresolved:" + "feeVO.listDutyRsn"); })())) == null ? '' : ((dma_feeVO.get("listDutyRsn") ?? (() => { throw new Error("unresolved:" + "feeVO.listDutyRsn"); })()))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("curDate") ?? ""))) + "\" /> "; } },
        { childId: "ipt_grntFee", fn: function () { return String(dma_feeVO.get("grntFee")) + "원"; } },
        { childId: "ipt_prepayBal", fn: function () { return String(dma_feeVO.get("prepayBal")) + "원"; } },
        { childId: "__rb1", fn: function () { return "가상계좌번호(" + String(String(String((dma_pageContext.get("returnAcntNo") ?? ""))).substring(0, 3)) + "-" + String(String(String((dma_pageContext.get("returnAcntNo") ?? ""))).substring(3, 6)) + "-" + String(String(String((dma_pageContext.get("returnAcntNo") ?? ""))).substring(6, 14)) + ")에 수수료(" + String(dma_feeVO.get("depoAmt")) + "원) 입금이 확인되었습니다."; } },
        { childId: "__rb5", fn: function () { return String(String((dma_pageContext.get("curDate") ?? ""))); } },
        { childId: "__rb6", fn: function () { return String(dma_feeVO.get("grntFee")) + "원"; } },
        { childId: "__rb8", fn: function () { return String(dma_feeVO.get("prepayBal")) + "원"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
