                scwin.fee_msg_2.setStyle("display", "none");
            } else {
                if ($c.util.getComponent('ipt_prepayBal').getValue() === '0' || ($c.util.getComponent('ipt_prepayBal').getValue() == null ? '' : String($c.util.getComponent('ipt_prepayBal').getValue())) === '') {
